// CDP screenshot runner: node shot.mjs jobs.json
// job: {file, out, width, height, wait, js (pre-eval), sel (element to clip), pad, maxH, y (scrollY clip), dark}
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const jobs = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const port = 9333;
const udd = path.join(path.dirname(process.argv[2]), 'chrome-udd');
const proc = spawn(CHROME, ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${udd}`,
  '--hide-scrollbars', '--no-first-run', '--force-device-scale-factor=1', 'about:blank'], { stdio: 'ignore' });

const sleep = ms => new Promise(r => setTimeout(r, ms));
let ver;
for (let i = 0; i < 50; i++) { try { ver = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); break; } catch { await sleep(200); } }
const target = ver.find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise(r => ws.onopen = r);
let id = 0; const pend = new Map(); const events = [];
ws.onmessage = m => { const d = JSON.parse(m.data); if (d.id && pend.has(d.id)) { pend.get(d.id)(d); pend.delete(d.id); } else events.push(d); };
const send = (method, params = {}) => new Promise(r => { const i = ++id; pend.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.result?.exceptionDetails) console.error('JS err', JSON.stringify(r.result.exceptionDetails).slice(0, 400)); return r.result?.result?.value; };

await send('Page.enable'); await send('Runtime.enable');
let lastFile = null, lastKey = null;
for (const j of jobs) {
  const w = j.width || 1280, h = j.height || 800;
  await send('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: j.scale || 1, mobile: false });
  await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: j.dark ? 'dark' : 'light' }] });
  const key = j.file + '|' + w;
  if (key !== lastKey || j.reload) {
    events.length = 0;
    await send('Page.navigate', { url: pathToFileURL(j.file).href });
    for (let i = 0; i < 300 && !events.find(e => e.method === 'Page.loadEventFired'); i++) await sleep(100);
    await sleep(j.wait ?? 1500);
    lastKey = key;
  }
  if (j.js) { await ev(`(async()=>{${j.js}})()`); await sleep(j.after ?? 600); }
  let clip;
  if (j.sel) {
    const r = await ev(`(()=>{const e=document.querySelector(${JSON.stringify(j.sel)}); if(!e) return null; const b=e.getBoundingClientRect(); return {x:b.left+scrollX,y:b.top+scrollY,w:b.width,h:b.height};})()`);
    if (!r) { console.error('no element', j.sel, j.out); continue; }
    const p = j.pad ?? 0;
    clip = { x: Math.max(0, r.x - p), y: Math.max(0, r.y - p), width: r.w + 2 * p, height: Math.min(r.h + 2 * p, j.maxH || 1e9), scale: 1 };
  } else {
    const y = j.y ?? await ev('scrollY');
    clip = { x: 0, y, width: w, height: j.clipH || h, scale: 1 };
  }
  const shot = await send('Page.captureScreenshot', { format: j.fmt || 'png', quality: j.fmt === 'jpeg' ? 82 : undefined, clip, captureBeyondViewport: true });
  if (!shot.result) { console.error('fail', j.out, JSON.stringify(shot.error)); continue; }
  fs.writeFileSync(j.out, Buffer.from(shot.result.data, 'base64'));
  console.log('ok', j.out, Math.round(clip.width) + 'x' + Math.round(clip.height));
}
ws.close(); proc.kill();
process.exit(0);

